const financeSupervisor = claude.supervisor({ grants: [H.ops.resolve(signoff)] });

const auditorClient = http.control({
  port: 8802,
  token: H.env('AUDITOR_TOKEN'),
  grants: [H.ops.readWork, H.ops.readTelemetry],
