  .input(experimentSchema)
  .loop('hourly', { schema: tally, initial: { a: 0, b: 0, hours: 0 } }, f => f
    .step('measure', measure, ctx => ({ slug: ctx.unit.attributes.slug }))
    .wait('nextHour', { ms: 3_600_000 }),
  {
