      databases.map(database => supply.create({ database }))
    )
  );

const renewals = H.lane('certificate-renewals', renewal)
  .handler(checkCertificate)
  .retries(1, { backoff: { first: { hours: 1 } }, exhausted: 'renewal-failed' })
  .suppliers(
