  const outcomes = metrics.outcomes({ of: experiments, window: { lastDays: 365 } });
  return {
    share: outcomes.terminal === 0 ? 0 : outcomes.of(Inconclusive) / outcomes.terminal,
    samples: outcomes.terminal,
  };
};

