  .input(z.object({ experiment: z.string(), metric: z.string() }))
  .output(readingSchema)
  .argv((input) => ['experiment-metric', '--experiment', input.experiment, '--metric', input.metric])
  .on(local)
  .retries(2, { first: { minutes: 1 } });

