  if (!scored.ok) return ctx.fail(scored.error);
  const summary = await ctx.run(summarizer, { checkpoint: ctx.unit.data.checkpoint, scores: scored.value });
  if (!summary.ok) return ctx.fail(summary.error);
  return 'scored';
});

