    of: 'durationMs',
    among: { entry: 'invocation', mode: 'external', executable: gpuJob, status: 'ended' },
    days: 1,
  });
  const gpuBudgetSpent = gpuToday.samples >= 5 && (gpuToday.value ?? 0) / 3_600_000 > 48;
