    if (unit.is(backfill)) return 10_000 + lockWaitMs(unit);
    return Number.MAX_SAFE_INTEGER;
  };
  return {
    start: [...view.pending].filter((unit) => !(gpuBudgetSpent && unit.is(evalRun))).sort((a, b) => rank(a) - rank(b)),
  };
});

