        H.ops.writeWork,
        H.ops.readTelemetry,
        H.ops.resolve(H.halts.interrupted, H.halts.definitionChanged),
      ],
    })
  )
  .observers(markdown.board('/srv/platform/.harness/board.md'), markdown.telemetry('/srv/platform/.harness/telemetry.md'));

