    if (!summary.ok) return ctx.fail(summary.error);
    const call = await ctx.halt(upsellCall, summary.value.summary, { customer, summary: summary.value.summary });
    if (call.action === 'churn') return 'churned';
    if (call.action === 'upsell') {
