        H.ops.readTelemetry,
        H.ops.resolve(upsellDecision, H.halts.exhausted, H.halts.interrupted, H.halts.definitionChanged),
      ],
    })
  )
  .observers(markdown.board('/srv/biz/.harness/board.md'), markdown.telemetry('/srv/biz/.harness/telemetry.md'));

