    when: ctx => ctx.steps.audit.deficits.length > 0,
  })
  .exit('shipped', ctx => ctx.steps.review === undefined || ctx.steps.review.verdict === 'accept')
  .exit('dropped', ctx => ctx.steps.review?.verdict === 'drop')
  .exit('reopened', {
