  .on(vendorAccepted, { update: (a, p) => ({ ...a, history: [...a.history, `them: ${p.message}`] }), enter: Agreed })
  .on(vendorWalkedAway, { update: (a, p) => ({ ...a, history: [...a.history, `them: ${p.message}`] }), enter: WalkedAwayByThem })
