  let totalA = 0;
  let totalB = 0;
  for (let hour = 0; hour < 14 * 24; hour += 1) {
    const reading = await ctx.run(sampleExperiment, { name: ctx.unit.data.name, metric: ctx.unit.data.metric });
    if (reading.ok) {
