  .on(local)
  .recovery('rerun');

const analyzeExperiment = H.command('analyze-experiment')
  .input(z.object({ experiment: z.string() }))
  .output(z.object({ winner: z.enum(['a', 'b', 'none']) }))
  .argv(input => ['bin/analyze', input.experiment])
  .on(local)
  .recovery('rerun');

