  .states(backfillQueued, backfilled, backfillFailed);

const countRows = H.command('count-rows')
  .input(z.object({ database: databaseSchema, table: z.string() }))
  .output(z.number())
  .argv(input => ['bin/count-rows', input.database, input.table])
