  .step('summary', usageSummarizer, ctx => ({
    task: `Customer ${ctx.unit.attributes.customerId} on ${ctx.unit.attributes.plan}: ${ctx.steps.usage.activeSeats} seats, $${ctx.steps.usage.spendUsd}. Summarize.`,
