const usageSummarizer = H.seat('usage-summarizer', usageSummaryRole).model(haiku);

const upsellCall = H.halt('upsell-call', z.object({ action: z.enum(['upsell', 'keep', 'churn']) })).about(
  z.object({ customer: z.string(), summary: z.string() })
