  .retries(3, { backoff: { first: { hours: 6 }, factor: 2 }, exhausted: 'review-stalled' })
  .suppliers(H.operator, reviewCalendar)
  .store(store(tenancy, '/srv/lifecycles/tenancies.sqlite'))
  .wip(3);
