  .handler(negotiationRound)
  .retries(2, { backoff: { first: { minutes: 30 } }, exhausted: 'stalled' })
  .suppliers(H.operator, vendorReplies)
  .store(store(negotiation, '/srv/lifecycles/negotiations.sqlite'))
  .wip(4);

